/* Pixel Stopwatch – cohesive palette: #2b2b2b (bg), #1e1e2f (card), #f0e6d2 (text), #ff6b6b (accent), #4ecdc4 (secondary) */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #2b2b2b;
  font-family: 'Courier New', Courier, monospace;
  font-size: 16px;
  padding: 16px;
}

.stopwatch {
  background: #1e1e2f;
  border: 4px solid #f0e6d2;
  border-radius: 0;
  padding: 24px 20px;
  width: 100%;
  max-width: 480px;
  box-shadow: 8px 8px 0 #000;
  text-align: center;
}

.title {
  font-size: 1.5rem;
  letter-spacing: 2px;
  color: #f0e6d2;
  margin-bottom: 16px;
  text-transform: uppercase;
}

.display {
  font-size: 3rem;
  font-weight: bold;
  color: #ff6b6b;
  background: #0f0f1a;
  border: 3px solid #f0e6d2;
  padding: 12px 8px;
  margin-bottom: 24px;
  letter-spacing: 4px;
  font-variant-numeric: tabular-nums;
  line-height: 1.2;
  word-break: break-all;
}

.controls {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  justify-content: center;
  margin-bottom: 24px;
}

.btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: bold;
  padding: 12px 20px;
  border: 3px solid #f0e6d2;
  border-radius: 0;
  background: #2b2b2b;
  color: #f0e6d2;
  cursor: pointer;
  text-transform: uppercase;
  letter-spacing: 1px;
  transition: background 0.1s, transform 0.1s;
  flex: 1 1 auto;
  min-width: 80px;
}

.btn:hover:not(:disabled) {
  background: #3a3a4a;
}

.btn:focus-visible {
  outline: 3px solid #4ecdc4;
  outline-offset: 2px;
}

.btn:active:not(:disabled) {
  transform: translate(2px, 2px);
  box-shadow: none;
}

.btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.btn.start {
  background: #4ecdc4;
  color: #1e1e2f;
  border-color: #4ecdc4;
}

.btn.start:hover:not(:disabled) {
  background: #3bb8b0;
}

.btn.stop {
  background: #ff6b6b;
  color: #1e1e2f;
  border-color: #ff6b6b;
}

.btn.stop:hover:not(:disabled) {
  background: #e55a5a;
}

.btn.lap {
  background: #f0e6d2;
  color: #1e1e2f;
  border-color: #f0e6d2;
}

.btn.lap:hover:not(:disabled) {
  background: #d9cfbb;
}

.btn.reset {
  background: #2b2b2b;
  color: #f0e6d2;
  border-color: #f0e6d2;
}

.btn.reset:hover:not(:disabled) {
  background: #3a3a4a;
}

.laps {
  text-align: left;
  border-top: 3px solid #f0e6d2;
  padding-top: 16px;
}

.laps-title {
  font-size: 1.2rem;
  color: #f0e6d2;
  margin-bottom: 12px;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.lap-list {
  list-style: none;
  max-height: 200px;
  overflow-y: auto;
}

.lap-list li {
  display: flex;
  justify-content: space-between;
  padding: 8px 4px;
  border-bottom: 2px solid #3a3a4a;
  color: #f0e6d2;
  font-size: 1rem;
}

.lap-list li:last-child {
  border-bottom: none;
}

.lap-list .lap-number {
  color: #4ecdc4;
  font-weight: bold;
}

.lap-list .lap-time {
  font-variant-numeric: tabular-nums;
}

@media (max-width: 400px) {
  .display {
    font-size: 2.2rem;
    letter-spacing: 2px;
  }
  .btn {
    font-size: 0.9rem;
    padding: 10px 12px;
  }
  .stopwatch {
    padding: 16px 12px;
  }
}

'use strict';

(function() {
  const display = document.getElementById('display');
  const startBtn = document.getElementById('startBtn');
  const stopBtn = document.getElementById('stopBtn');
  const lapBtn = document.getElementById('lapBtn');
  const resetBtn = document.getElementById('resetBtn');
  const lapList = document.getElementById('lapList');

  let startTime = 0;
  let elapsed = 0;
  let running = false;
  let rafId = null;
  let laps = [];

  function formatTime(ms) {
    const totalCs = Math.floor(ms / 10);
    const cs = totalCs % 100;
    const totalSec = Math.floor(ms / 1000);
    const sec = totalSec % 60;
    const min = Math.floor(totalSec / 60);
    return String(min).padStart(2, '0') + ':' + String(sec).padStart(2, '0') + '.' + String(cs).padStart(2, '0');
  }

  function updateDisplay() {
    const current = running ? elapsed + (performance.now() - startTime) : elapsed;
    display.textContent = formatTime(current);
    if (running) {
      rafId = requestAnimationFrame(updateDisplay);
    }
  }

  function start() {
    if (running) return;
    running = true;
    startTime = performance.now();
    startBtn.disabled = true;
    stopBtn.disabled = false;
    lapBtn.disabled = false;
    resetBtn.disabled = false;
    rafId = requestAnimationFrame(updateDisplay);
  }

  function stop() {
    if (!running) return;
    running = false;
    elapsed += performance.now() - startTime;
    if (rafId) cancelAnimationFrame(rafId);
    rafId = null;
    startBtn.disabled = false;
    stopBtn.disabled = true;
    lapBtn.disabled = true;
    updateDisplay();
  }

  function lap() {
    if (!running) return;
    const current = elapsed + (performance.now() - startTime);
    const lapTime = current - (laps.length ? laps[laps.length - 1].total : 0);
    laps.push({ total: current, lapTime: lapTime });
    renderLaps();
  }

  function reset() {
    if (running) {
      running = false;
      if (rafId) cancelAnimationFrame(rafId);
      rafId = null;
    }
    elapsed = 0;
    laps = [];
    startBtn.disabled = false;
    stopBtn.disabled = true;
    lapBtn.disabled = true;
    resetBtn.disabled = true;
    display.textContent = formatTime(0);
    renderLaps();
  }

  function renderLaps() {
    lapList.innerHTML = '';
    laps.forEach((lap, index) => {
      const li = document.createElement('li');
      li.innerHTML = '<span class="lap-number">Lap ' + (index + 1) + '</span><span class="lap-time">' + formatTime(lap.lapTime) + '</span>';
      lapList.appendChild(li);
    });
  }

  startBtn.addEventListener('click', start);
  stopBtn.addEventListener('click', stop);
  lapBtn.addEventListener('click', lap);
  resetBtn.addEventListener('click', reset);

  // Initialize display
  display.textContent = formatTime(0);
})();
